html:
{% set pos = frappe.get_doc("POS Invoice", doc.pos_invoice) %}
{% set company_doc = frappe.get_doc("Company", doc.company) %}
{% set company_address = frappe.get_doc("Address", doc.billing_address) if doc.billing_address else None %}


{% macro thai_group(value) -%}
    {% set ns = namespace(out="") %}
    {% for unit, label in [
        (100000, "แสน"),
        (10000, "หมื่น"),
        (1000, "พัน"),
        (100, "ร้อย"),
        (10, "สิบ"),
        (1, "")
    ] %}
        {% set digit = (value // unit) % 10 %}
        {% if digit %}
            {% if unit == 10 and digit == 1 %}
                {% set ns.out = ns.out ~ "สิบ" %}
            {% elif unit == 10 and digit == 2 %}
                {% set ns.out = ns.out ~ "ยี่สิบ" %}
            {% elif unit == 1 and digit == 1 and value > 1 %}
                {% set ns.out = ns.out ~ "เอ็ด" %}
            {% else %}
                {% set words = ["", "หนึ่ง", "สอง", "สาม", "สี่", "ห้า", "หก", "เจ็ด", "แปด", "เก้า"] %}
                {% set ns.out = ns.out ~ words[digit] ~ label %}
            {% endif %}
        {% endif %}
    {% endfor %}
    {{- ns.out -}}
{%- endmacro %}

{% macro thai_integer(value) -%}
    {% if value >= 1000000 %}
        {{- thai_integer(value // 1000000) -}}ล้าน
    {% endif %}
    {{- thai_group(value % 1000000) -}}
{%- endmacro %}

<style>
    @page {
        size: A4;
        margin: 12mm 12mm 12mm 12mm;
    }

    body {
        font-family: Tahoma, Arial, sans-serif;
        font-size: 13px;
        color: #333;
        margin: 0;
        padding: 0;
        background: #fff;
    }

    .invoice-box {
        width: 100%;
        margin: auto;
        padding: 5px;
        background: #fff;
    }

    .header-table,
    .info-table,
    .item-table,
    .total-table {
        width: 100%;
        border-collapse: collapse;
    }

    .header-table td,
    .info-table td {
        vertical-align: top;
        padding: 5px;
    }

    .company-logo {
        width: 90px;
        max-height: 85px;
        object-fit: contain;
        margin-right: 12px;
    }

    .company-info {
        line-height: 1.6;
    }

    .company-info h3 {
        font-size: 17px;
        margin: 0 0 5px 0;
        color: #222;
    }

    .title-box {
        text-align: right;
        line-height: 1.5;
    }

    .title-box h2 {
        margin: 0 0 5px 0;
        font-size: 20px;
        color: #2c3e50;
    }

    .english-title {
        color: #c0392b;
        font-weight: bold;
        font-size: 14px;
    }

    .customer-box {
        border: 1px solid #ccc;
        padding: 12px;
        margin-top: 15px;
        margin-bottom: 15px;
        border-radius: 4px;
        background: #fafafa;
        line-height: 1.8;
    }

    .item-table {
        margin-top: 10px;
    }

    .item-table th,
    .item-table td {
        border: 1px solid #bdc3c7;
        padding: 7px;
    }

    .item-table th {
        background: #2c3e50;
        color: white;
        text-align: center;
        font-weight: bold;
    }

    .item-table td {
        vertical-align: top;
    }

    .text-right {
        text-align: right !important;
    }

    .text-center {
        text-align: center !important;
    }

    .total-table {
        margin-top: 12px;
    }

    .total-table td {
        padding: 6px;
        vertical-align: top;
    }

    .grand-total {
        font-weight: bold;
        background: #f1f2f6;
        border-top: 1px solid #777;
        border-bottom: 1px solid #777;
    }

    .signature-section {
        margin-top: 45px;
        width: 100%;
    }

    .signature-box {
        width: 45%;
        float: left;
        text-align: center;
        margin-top: 20px;
    }

    .signature-line {
        border-bottom: 1px dotted #333;
        height: 40px;
        margin-bottom: 5px;
    }

    .clearfix::after {
        content: "";
        clear: both;
        display: table;
    }

    .small-text {
        font-size: 11px;
        color: #555;
    }

    .source-reference {
        margin-top: 15px;
        font-size: 11px;
        color: #666;
    }

    @media print {
        body {
            background: #fff;
        }

        .invoice-box {
            border: none;
            box-shadow: none;
        }

        .item-table thead {
            display: table-header-group;
        }

        .item-table tr {
            page-break-inside: avoid;
        }
    }
</style>

<div class="invoice-box">

    <!-- HEADER -->
    <table class="header-table">
        <tr>
            <td style="width: 60%;">
                <table>
                    <tr>
                        {% if company_doc.company_logo %}
                        <td style="width: 100px; vertical-align: top;">
                            <img
                                src="{{ frappe.utils.get_url(company_doc.company_logo) }}"
                                class="company-logo">
                        </td>
                        {% endif %}

                        <td class="company-info">
                            <h3>
                                {{ company_doc.company_name or company_doc.name }}
                            </h3>

                            {% if company_address %}
                                {% if company_address.address_line1 %}
                                    {{ company_address.address_line1 }}<br>
                                {% endif %}
                                {% if company_address.address_line2 %}
                                    {{ company_address.address_line2 }}<br>
                                {% endif %}
                                {% if company_address.city %}
                                    {{ company_address.city }}
                                {% endif %}
                                {% if company_address.state %}
                                    {{ company_address.state }}
                                {% endif %}
                                {% if company_address.pincode %}
                                    {{ company_address.pincode }}
                                {% endif %}
                                {% if company_address.country %}
                                    {{ company_address.country }}
                                {% endif %}
                                <br>

                                {% if company_address.phone %}
                                    โทรศัพท์: {{ company_address.phone }}<br>
                                {% endif %}

                                {% if company_address.email_id %}
                                    อีเมล: {{ company_address.email_id }}<br>
                                {% endif %}
                            {% endif %}

                            {% if company_address and company_address.tax_id %}
                                <strong>เลขประจำตัวผู้เสียภาษี:</strong>
                                {{ company_address.tax_id }}
                            {% endif %}
                        </td>
                    </tr>
                </table>
            </td>

            <td class="title-box" style="width: 40%;">
                <h2>ใบกำกับภาษี / ใบเสร็จรับเงิน</h2>
                <div class="english-title">
                    TAX INVOICE / RECEIPT
                </div>

                <p>
                    <strong>เลขที่:</strong>
                    {{ doc.full_tax_invoice_number or "-" }}
                </p>

                <p>
                    <strong>วันที่:</strong>
                    {{ frappe.utils.formatdate(doc.full_tax_invoice_date, "dd/MM/yyyy") if doc.full_tax_invoice_date else "-" }}
                </p>

            </td>
        </tr>
    </table>

    <!-- CUSTOMER -->
    <div class="customer-box">
        <table style="width: 100%; border-collapse: collapse;">
            <tr>
                <td style="width: 60%; vertical-align: top;">
                    <strong>นามผู้ซื้อ / ลูกค้า:</strong>
                    {{ doc.buyer_name or doc.original_customer_name or "-" }}
                </td>
                <td style="width: 40%; text-align: right; vertical-align: top; white-space: nowrap;">
                    <strong>เลขประจำตัวผู้เสียภาษี:</strong>
                    {{ doc.buyer_tax_id or "-" }}
                </td>
            </tr>
            <tr>
                <td style="vertical-align: top;">
                    <strong>ที่อยู่:</strong>
                    {{ doc.buyer_address or "-" }}
                </td>
                <td style="text-align: right; vertical-align: top; white-space: nowrap;">
                    {% if doc.buyer_branch %}
                        <strong>สาขา:</strong>
                        {{ doc.buyer_branch }}
                    {% endif %}
                </td>
            </tr>
        </table>
    </div>

    <!-- ITEMS FROM ORIGINAL POS INVOICE -->
    <table class="item-table">
        <thead>
            <tr>
                <th style="width: 8%;">ลำดับ</th>
                <th style="width: 42%;">รายการสินค้า / บริการ</th>
                <th style="width: 12%;">จำนวน</th>
                <th style="width: 17%;">หน่วยละ</th>
                <th style="width: 21%;">จำนวนเงิน (บาท)</th>
            </tr>
        </thead>

        <tbody>
            {% for item in pos.items %}
            <tr>
                <td class="text-center">{{ loop.index }}</td>

                <td>
                    <strong>{{ item.item_name or item.item_code }}</strong>

                    {% if item.description and item.description != item.item_name %}
                        <br>
                        <span class="small-text">
                            {{ item.description }}
                        </span>
                    {% endif %}
                </td>

                <td class="text-center">
                    {{ frappe.utils.fmt_money(item.qty, precision=2) }}
                    {{ item.uom or "" }}
                </td>

                <td class="text-right">
                    {{ frappe.utils.fmt_money(item.rate, precision=2) }}
                </td>

                <td class="text-right">
                    {{ frappe.utils.fmt_money(item.amount, precision=2) }}
                </td>
            </tr>
            {% endfor %}
        </tbody>
    </table>

    <!-- TOTALS -->
    <table class="total-table">
        <tr>
            <td style="width: 57%; vertical-align: bottom;">
                <p>
                    <strong>จำนวนเงินรวม (ตัวอักษร):</strong>
                </p>

                <p>
                    {% set amount_parts = ("%.2f"|format(doc.original_grand_total or 0)).split(".") %}
{{ thai_integer(amount_parts[0]|int) }}บาท{% if amount_parts[1]|int == 0 %}ถ้วน{% else %}{{ thai_integer(amount_parts[1]|int) }}สตางค์{% endif %}
                </p>

                <p class="source-reference">
                    อ้างอิง POS Invoice: {{ doc.pos_invoice }}
                </p>
            </td>

            <td style="width: 43%;">
                <table style="width: 100%; border-collapse: collapse;">
                    <tr>
                        <td>มูลค่าสินค้า/บริการ:</td>
                        <td class="text-right">
                            {{ frappe.utils.fmt_money(doc.original_net_total or 0, precision=2) }}
                        </td>
                        <td>บาท</td>
                    </tr>

                    <tr>
                        <td>ภาษีมูลค่าเพิ่ม (VAT):</td>
                        <td class="text-right">
                            {{ frappe.utils.fmt_money(doc.original_vat_amount or 0, precision=2) }}
                        </td>
                        <td>บาท</td>
                    </tr>

                    <tr class="grand-total">
                        <td>จำนวนเงินรวมทั้งสิ้น:</td>
                        <td class="text-right">
                            {{ frappe.utils.fmt_money(doc.original_grand_total or 0, precision=2) }}
                        </td>
                        <td>บาท</td>
                    </tr>
                </table>
            </td>
        </tr>
    </table>

    <!-- SIGNATURE -->
    <div class="signature-section clearfix">
        <div class="signature-box">
            <div class="signature-line"></div>
            <p>ผู้รับสินค้า / Customer</p>
            <p>วันที่: _____/_____/_____</p>
        </div>

        <div class="signature-box" style="float: right;">
            <div class="signature-line"></div>
            <p>ผู้มีอำนาจลงนาม / Authorized Signature</p>
            <p>วันที่: _____/_____/_____</p>
        </div>
    </div>

</div>
